#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_insert_empty_list(void) {
    node *root = NULL;
    int id = 1;
    int at = 0;
    int bt = 5;
    int prior = 1;

    insert(&root, id, at, bt, prior);

    TEST_ASSERT_NOT_NULL(root);
    TEST_ASSERT_EQUAL_INT(1, root->ID);
